SCENARIOS: list[RevisionStep] = [
    AUserAddsARevision(started=datetime.now(UTC)),
    AUserGrantedNothingMayNotAddARevision(),
    AUserSearchesRevisions(started=datetime.now(UTC)),
    AUserGrantedNothingMayNotSearchRevisions(),
    AUserLoadsARevision(started=datetime.now(UTC)),
    AUserGrantedNothingGetsARefusalForARevision(),
]


@pytest.mark.parametrize("scenario", SCENARIOS, ids=lambda s: s.summary())
async def test_v2_revisions(
    scenario: RevisionStep,
    auto_generated_file_adapter: AutoGeneratedFileAdapter,
    engine: ExtendedAsyncSAEngine,
) -> None:
    await run_scenario(scenario, auto_generated_file_adapter, engine)
    match scenario:
        case AUserAddsARevision():
            assert await config_files_left(engine) == [
                (
                    CONFIG_PATH,
                    False,
                    [(1, CONFIG_PERMISSION, CONFIG_DATA), (2, UPDATED_PERMISSION, UPDATED_DATA)],
                )
            ]
        case AUserGrantedNothingMayNotAddARevision():
            assert await config_files_left(engine) == [
                (CONFIG_PATH, False, [(1, CONFIG_PERMISSION, CONFIG_DATA)])
            ]
